    {
        return new self(
            getenv('CLKLOG_ENDPOINT') ?: '<Report-URL>',
            getenv('CLKLOG_PROJECT') ?: '<Projektname>',
            getenv('CLKLOG_TOKEN') ?: throw new RuntimeException('CLKLOG_TOKEN fehlt'),
            10,
        );
    }
}

