type Event struct {
    Type       string         `json:"type"`                 // track / track_signup / user_set
    Event      string         `json:"event,omitempty"`      // Ereignisname (bei track erforderlich)
    DistinctID string         `json:"distinct_id"`          // Besucher-ID
    Time       int64          `json:"time"`                 // Zeitstempel in Millisekunden
    Identities map[string]any `json:"identities,omitempty"` // {"user_key": Anmelde-ID}
    Properties map[string]any `json:"properties,omitempty"`
}

type ClkLogClient struct {
    Endpoint, Project, Token string
    BatchSize                int
    loginID                  string
    queue                    []Event
    http                     *http.Client
}

func NewClkLogClient(endpoint, project, token string) *ClkLogClient {
    return &ClkLogClient{
        Endpoint: endpoint, Project: project, Token: token, BatchSize: 10,
        http: &http.Client{Timeout: 10 * time.Second},
    }
}

