func (c *ClkLogClient) Flush() error {
    if len(c.queue) == 0 {
        return nil
    }
    payload, err := json.Marshal(c.queue)
    if err != nil {
        return fmt.Errorf("marshal: %w", err)
    }
    form := url.Values{}
    form.Set("project", c.Project)
    form.Set("token", c.Token)
    form.Set("data", base64.StdEncoding.EncodeToString(payload))

    var lastErr error
    for attempt := 1; attempt <= 3; attempt++ {
        req, _ := http.NewRequest(http.MethodPost, c.Endpoint, bytes.NewBufferString(form.Encode()))
        req.Header.Set("Content-Type", "application/x-www-form-urlencoded")
        resp, err := c.http.Do(req)
        if err == nil && resp.StatusCode == http.StatusOK {
            io.Copy(io.Discard, resp.Body)
            resp.Body.Close()
            c.queue = c.queue[:0]
            return nil
        }
        if err == nil {
            body, _ := io.ReadAll(resp.Body)
            resp.Body.Close()
            lastErr = fmt.Errorf("http %d: %s", resp.StatusCode, string(body))
        } else {
            lastErr = err
        }
        time.Sleep(time.Duration(attempt) * 500 * time.Millisecond) // Backoff
    }
    return fmt.Errorf("flush failed after 3 attempts: %w", lastErr)
}

