public sealed class ClkLogClient
{
    private readonly HttpClient _http;
    private readonly string _endpoint, _project, _token;
    private readonly int _batchSize;
    private readonly List<Dictionary<string, object?>> _queue = new();
    private string? _loginId;

    public ClkLogClient(string endpoint, string project, string token, int batchSize = 10)
    {
        _endpoint = endpoint;
        _project = project;
        _token = token;
        _batchSize = batchSize > 0 ? batchSize : 10;
        _http = new HttpClient { Timeout = TimeSpan.FromSeconds(10) };
    }
}

