public async Task FlushAsync()
{
    if (_queue.Count == 0) return;
    var json = JsonSerializer.Serialize(_queue);
    var payload = Convert.ToBase64String(Encoding.UTF8.GetBytes(json));

    for (var attempt = 1; attempt <= 3; attempt++)
    {
        try
        {
            using var content = new FormUrlEncodedContent(new Dictionary<string, string>
            {
                ["project"] = _project,
                ["token"] = _token,
                ["data"] = payload,
            });
            var res = await _http.PostAsync(_endpoint, content);
            if (res.IsSuccessStatusCode)
            {
                _queue.Clear();
                return;
            }
        }
        catch (Exception) when (attempt < 3)
        {
            // Netzwerkfehler mit Backoff erneut versuchen
        }
        await Task.Delay(attempt * 500);
    }
    // Nach drei Fehlversuchen: Warteschlange behalten und beim nächsten Auslösen senden (optional in eine lokale Datei persistieren)
}
